BRIEF:
{
 "id": "shared_queue",
 "description": "A network of 2 hosts: sender, receiver. Link l1 joins sender and receiver: it carries 1Gbps with a one-way delay of 50us. On sender's side packets wait in one queue of the knob l1.queue.length packets; a packet that arrives when it is full is dropped. Flow udp is UDP from sender to receiver: packets of 1400 bytes at a constant rate (2 Gbps). Flow tcp is TCP from sender to receiver: it always has data to send; its congestion control is the knob tcp.type. A host with more than one link forwards packets. In each simulation the flows start within the first 10 ms, traffic runs for one second that is not measured, and then for duration seconds, over which the outputs are measured.",
 "topology": {
  "hosts": [
   {
    "id": "sender"
   },
   {
    "id": "receiver"
   }
  ],
  "links": [
   {
    "id": "l1",
    "between": [
     "sender",
     "receiver"
    ],
    "rate": "1Gbps",
    "delay": "50us",
    "mtu": 1500,
    "device_queue": 10,
    "queue": {
     "on": "sender",
     "kind": "fifo",
     "length": 100
    }
   }
  ],
  "flows": [
   {
    "id": "udp",
    "kind": "udp",
    "from": "sender",
    "to": "receiver",
    "rate": "2 Gbps",
    "packet_bytes": 1400
   },
   {
    "id": "tcp",
    "kind": "tcp",
    "from": "sender",
    "to": "receiver",
    "type": "TcpCubic"
   }
  ]
 },
 "system": {
  "seed": 1,
  "duration": 10
 },
 "knobs": {
  "l1.queue.length": {
   "min": 4,
   "max": 1000,
   "default": 100,
   "meaning": "queue length at l1"
  },
  "tcp.type": {
   "choices": [
    "TcpCubic",
    "TcpNewReno",
    "TcpLinuxReno",
    "TcpBbr",
    "TcpVegas",
    "TcpBic"
   ],
   "default": "TcpCubic",
   "meaning": "TCP type of tcp (TCP congestion control)"
  }
 },
 "goal": {
  "kind": "given",
  "target": {
   "measure": "tcp_goodput_bps",
   "direction": "max"
  },
  "conditions": []
 },
 "limits": {
  "simulations": 12,
  "simulations_per_experiment": 4
 },
 "structure": {
  "may_change": true,
  "most": {
   "hosts": 2,
   "links": 1,
   "flows": 2
  },
  "locked": [
   "host:sender",
   "flow:udp",
   "link:l1",
   "host:receiver"
  ]
 },
 "task": "Find the settings that give the largest tcp_goodput_bps. You may change 2 settings (l1.queue.length, tcp.type); every other setting is fixed. Explain why they are best.",
 "outputs": {
  "udp_goodput_bps": "payload bits per second delivered to the receiver of flow udp (receiver)",
  "udp_loss_frac": "fraction of the packets flow udp sent that never arrived",
  "tcp_goodput_bps": "payload bits per second delivered to the receiver of flow tcp (receiver)",
  "tcp_retrans": "TCP segments the sender of flow tcp sent again",
  "l1_util": "bits sent on link l1 from sender to receiver, divided by the link's rate",
  "l1_util_back": "the same from receiver to sender",
  "l1_drops": "packets dropped from the queue in front of link l1 on the side of sender",
  "l1_drops_back": "packets dropped from the plain queue in front of link l1 on the side of receiver"
 },
 "tools": {
  "describe_system": "this brief, with the descriptions of the outputs and the tools",
  "metrics": "metrics(run_id): the output values of a simulation (run ids are in the evidence lines, e.g. r003)",
  "series": "series(run_id, every_n): per-100ms samples of a run: t, then for each flow <flow>_bps (and <flow>_cwnd for a TCP flow), then for each described queue the packets waiting at the sample time (<link>_q_<flow> for a scheduler's queue, named after its flow or its class; <link>_q for a plain queue) and the packets dropped since traffic began (<link>_drops_<flow>, <link>_drops) (at most 100 rows; the measured seconds begin at t = 2)",
  "measure": "measure(run_id, of, stat, t_from, t_to, level): a measurement you define, computed from what a simulation recorded over time (nothing is simulated again, and it costs no simulation). of: a column or arithmetic over columns of one record, by the names of this network (the bits per second of two flows added, or, once the simulation has its probe, a flow's bytes in flight divided by its receiver's window: <flow>_inflight / <flow>_rwnd); stat: mean, min, max, std, first, last, p05, p50, p95, slope (change per second), rate ((last - first) / seconds, for a column that counts up), time_above, time_below (seconds spent above or below level), first_time_above, first_time_below; t_from, t_to: the window in seconds (left out: the measured seconds, from 2 s to the end)",
  "probe": "probe(run_id, every): a finer look at a simulation you already ran. The harness runs the same simulation again (same settings, same seed) with trace sinks that only listen, and keeps their record only if the result is byte for byte the same: no result can change by it, and it costs no simulation. Sampled every `every` seconds (left out: 0.01), it records, for each flow, <flow>_bps, and for a TCP flow <flow>_cwnd, <flow>_ssthresh, <flow>_inflight (bytes sent and not yet acknowledged), <flow>_rwnd (the receiver's window as the sender knows it), <flow>_rtt_ms and <flow>_rto_ms; for each described queue the longest time a packet waited in it since the last sample (<link>_wait_<flow or class>_ms for a scheduler's queue, <link>_wait_ms for a plain one) and the packets waiting; for each link the packets in its devices' transmit queues (<link>_devq, <link>_devq_back). It answers with the columns it recorded; read them with measure, or with series(run_id, every_n, probe=true)",
  "list_runs": "list_runs(): id, params and metrics of every simulation of this session so far"
 },
 "how_to_run": "An experiment is a set of simulations with one purpose, run at once. Fill the 'experiment' field of your answer: its kind (test or explore), the simulations (runs: a label and the params that differ from the defaults), and for a test the decision rules, comparisons stated before the simulations run. The harness runs the simulations, appends the evidence (one line per simulation) and checks every decision rule itself.",
 "budget": "the budget counts simulations; the number left is stated in each turn"
}

SIMULATION BUDGET: 12 simulations left (12 granted so far; budget_request can raise that to at most 12, the brief's limit). This turn's experiment may run at most 4 new simulations: never more than half of what is left, so that something remains for what its results raise.

TOLERANCE: two results that differ by less than 1 % count as equal (the default of the harness: the brief states none). A difference inside it is not a finding, and a setting is not better for it.

LEDGER:
[X0] turn 0 experiment explore: what the system does with every setting at its default (run by the harness before turn 1) | simulations: default {defaults}
[E0] turn 0 evidence of X0, one line per simulation (label, run id, settings changed from the defaults | measured):
    default r001 defaults | udp_goodput_bps=979021120 udp_loss_frac=0.510489 tcp_goodput_bps=0 tcp_retrans=3 l1_util=0.999999 l1_util_back=0.0 l1_drops=911591 l1_drops_back=0

answer:
{
 "observations": "Default run r001: udp_goodput_bps=979021120, udp_loss_frac=0.510489, tcp_goodput_bps=0, tcp_retrans=3, l1_util=0.999999, l1_util_back=0.0, l1_drops=911591. The link is saturated by UDP, UDP loses about half its packets, and TCP delivers nothing. The most important unexplained fact is l1_util_back=0.0: there is no reverse traffic at all, so either the TCP connection never establishes or no TCP data is ever acknowledged. I need to know whether the forward queue is persistently full and whether TCP is stuck with tiny cwnd/large RTO, and whether queue length or TCP type can create any meaningful TCP goodput.",
 "rethink": [],
 "whys": [
  {
   "about": ["E0"],
   "result": "TCP goodput is zero while UDP gets 979 Mbps and the link is 100% utilized.",
   "guess": "UDP's 2 Gbps offered load keeps the FIFO queue at l1 full, so TCP packets (handshake or data) are tail-dropped and never acknowledged.",
   "unseen": "Queue occupancy near l1.queue.length, TCP cwnd stuck near 1, large RTO, and no ACK packets on the reverse direction.",
   "matters": "If true, the goal requires a setting or structure that creates queue space or gives TCP a protected share; otherwise TCP remains zero.",
   "worth": "verify",
   "reason": "This is the direct cause of zero TCP goodput and can be checked with probe/measure without spending simulations."
  ,
  "revises": null
  },
  {
   "about": ["E0"],
   "result": "Default queue length 100 gives TCP zero.",
   "guess": "Queue length controls whether TCP can get packets into the queue: a very small queue may leave more frequent empty slots, while a very large queue may let TCP bursts survive once they enter.",
   "unseen": "The relationship between queue length and TCP packet admission probability / queueing delay.",
   "matters": "If queue length matters, the optimum may be at an extreme (4 or 1000) rather than the default.",
   "worth": "verify",
   "reason": "l1.queue.length is one of the two allowed knobs, and testing extremes can reveal whether TCP can be unblocked at all."
  ,
  "revises": null
  },
  {
   "about": ["E0"],
   "result": "TCP Cubic gets zero under UDP saturation.",
   "guess": "The congestion-control algorithm may matter: BBR, which estimates bandwidth/RTT and paces rather than relying only on loss, might obtain nonzero goodput where Cubic collapses.",
   "unseen": "BBR's delivery-rate estimate and pacing behavior in a queue dominated by unresponsive UDP.",
   "matters": "tcp.type is the other allowed knob; if BBR can obtain meaningful goodput, it may be the recommended type.",
   "worth": "verify",
   "reason": "Testing BBR at queue extremes can separate an algorithm effect from a pure queue-admission effect."
  ,
  "revises": null
  }
 ],
 "hypotheses": [
  {
   "from_why": "Y1",
   "text": "In the default run, the l1 queue is persistently full and TCP is stuck with very small cwnd/large RTO, so TCP packets are dropped before any ACK is generated.",
   "question": "Is the default TCP failure caused by a full queue and a stuck TCP sender?",
   "why": "If true, only settings that create queue space or protect TCP can improve the goal.",
   "prediction": "probe/measure on r001 will show mean l1_q close to 100 packets, mean tcp_cwnd below 10 packets, and no meaningful reverse ACK traffic.",
   "follows_from": ["E0"]
  },
  {
   "from_why": "Y2",
   "text": "For Cubic, changing queue length from 4 to 1000 changes TCP goodput by more than tolerance; one of these queue lengths lets TCP obtain meaningful goodput.",
   "question": "Does queue length let Cubic obtain meaningful TCP goodput?",
   "why": "Queue length is a knob that may determine whether TCP packets can enter the queue.",
   "prediction": "At least one of cubic_q4 or cubic_q1000 has tcp_goodput_bps > 10000000, and the two values differ by more than 1%.",
   "follows_from": ["E0"]
  },
  {
   "from_why": "Y3",
   "text": "For BBR, changing queue length from 4 to 1000 changes TCP goodput by more than tolerance; one of these queue lengths lets BBR obtain meaningful goodput.",
   "question": "Does BBR obtain meaningful TCP goodput at some queue length?",
   "why": "BBR may behave differently from Cubic under UDP-induced loss.",
   "prediction": "At least one of bbr_q4 or bbr_q1000 has tcp_goodput_bps > 10000000, and the two values differ by more than 1%.",
   "follows_from": ["E0"]
  }
 ],
 "drop": [],
 "experiment": {
  "kind": "test",
  "tests": ["H2", "H3"],
  "question": "",
  "needs": [
   {
    "for": "H2",
    "to_know": "Whether Cubic obtains meaningful TCP goodput at a very small or very large queue length, and whether queue length changes it.",
    "varies": "l1.queue.length",
    "measure": "tcp_goodput_bps",
    "simulations": ["cubic_q4", "cubic_q1000"]
   },
   {
    "for": "H3",
    "to_know": "Whether BBR obtains meaningful TCP goodput at a very small or very large queue length, and whether queue length changes it.",
    "varies": "l1.queue.length",
    "measure": "tcp_goodput_bps",
    "simulations": ["bbr_q4", "bbr_q1000"]
   }
  ],
  "measurements": [],
  "varied": ["l1.queue.length", "tcp.type"],
  "control": null,
  "runs": [
   {
    "label": "cubic_q4",
    "params": {
     "l1.queue.length": 4,
     "tcp.type": "TcpCubic"
    }
   ,
   "structure": []
   },
   {
    "label": "cubic_q1000",
    "params": {
     "l1.queue.length": 1000,
     "tcp.type": "TcpCubic"
    }
   ,
   "structure": []
   },
   {
    "label": "bbr_q4",
    "params": {
     "l1.queue.length": 4,
     "tcp.type": "TcpBbr"
    }
   ,
   "structure": []
   },
   {
    "label": "bbr_q1000",
    "params": {
     "l1.queue.length": 1000,
     "tcp.type": "TcpBbr"
    }
   ,
   "structure": []
   }
  ],
  "decision_rules": [
   {
    "for": "H2",
    "decision_rule": "(tcp_goodput_bps@cubic_q4 > 10000000 OR tcp_goodput_bps@cubic_q1000 > 10000000) AND abs(tcp_goodput_bps@cubic_q1000 - tcp_goodput_bps@cubic_q4) > 0.01 * max(tcp_goodput_bps@cubic_q1000, tcp_goodput_bps@cubic_q4, 1)",
    "rival": "UDP saturation makes TCP goodput zero or equal for all queue lengths with Cubic.",
    "rival_predicts": "failed"
   },
   {
    "for": "H3",
    "decision_rule": "(tcp_goodput_bps@bbr_q4 > 10000000 OR tcp_goodput_bps@bbr_q1000 > 10000000) AND abs(tcp_goodput_bps@bbr_q1000 - tcp_goodput_bps@bbr_q4) > 0.01 * max(tcp_goodput_bps@bbr_q1000, tcp_goodput_bps@bbr_q4, 1)",
    "rival": "UDP saturation makes TCP goodput zero or equal for all queue lengths with BBR.",
    "rival_predicts": "failed"
   }
  ]
 },
 "verdicts": [],
 "report": null,
 "requests": [
  {
   "tool": "probe",
   "args": {
    "run_id": "r001",
    "every": 0.01
   }
  },
  {
   "tool": "measure",
   "args": {
    "run_id": "r001",
    "of": "l1_q",
    "stat": "mean",
    "t_from": null,
    "t_to": null,
    "level": null
   }
  },
  {
   "tool": "measure",
   "args": {
    "run_id": "r001",
    "of": "tcp_cwnd",
    "stat": "mean",
    "t_from": null,
    "t_to": null,
    "level": null
   }
  }
 ],
 "budget_request": null,
 "done": false
}

{
  "follows": true,
  "because": "The guess claims BBR's pacing and estimation allow it to get goodput where Cubic fails; testing if BBR achieves goodput validates this mechanism."
}

